/**
 * VIBE CORP — brand root.
 *
 * The single source of truth for the mark, the palette and the type scale.
 * Everything downstream reads from here: the React components in
 * components/brand, the standalone SVGs in /brand (generated by
 * scripts/export-brand.mjs), and eventually the site.
 *
 * The mark is drawn on a 150x150 canvas. It is NOT geometrically perfect —
 * the disc and the inner ring are both slightly irregular, hand-drawn circles,
 * and the whole mark sits about one unit high of centre. That is deliberate
 * and preserved: Vibe Corp is old and accreted, and a mark struck by hand a
 * long time ago should not measure like one struck by a machine. Do not
 * "correct" these paths to true circles.
 */

export const MARK_VIEWBOX = "0 0 150 150";

/** Optical centre of the mark — the disc, ring and waves all agree on this,
 *  and it is NOT (75, 75). Anything concentric with the mark uses this. */
export const MARK_CENTER = { x: 75, y: 74.2 } as const;

