/**
 * PALETTE.
 *
 * Lifted out of the deck, where it was already locked, and given roles. The
 * hex values are unchanged — the cards, the back and the stickers must be the
 * same outfit.
 *
 * `signal` is the one that matters: mustard is Vibe Corp's single signal
 * colour. It marks the thing you are meant to read. Everything else is ground,
 * ink, or band.
 */
export const PALETTE = {
  // Grounds — what brand surfaces sit on.
  black: { hex: "#000000", role: "Deep ground. Cosmic backdrop, sticker die-cut ground." },
  ink: { hex: "#0b0b0c", role: "The disc. Near-black with a hint of warmth." },
  plum: { hex: "#251435", role: "The working ground. Plates, panels, page." },
  // Ink — what sits on the grounds.
  cream: { hex: "#f3e9d6", role: "Body ink on dark. Never pure white." },
  // Signal — the one colour that means 'read this'.
  mustard: { hex: "#e8a929", role: "SIGNAL. Rules, borders, the one true line, the seal's type." },
  // Bands — the wave pattern and illustration. Never used for type.
  teal: { hex: "#2fa090", role: "Band." },
  blue: { hex: "#3358c4", role: "Band." },
  purple: { hex: "#a274d6", role: "Band. Also the uniform — crew hi-vis." },
  rose: { hex: "#dd8296", role: "Band." },
  brick: { hex: "#c4462a", role: "Band." },
} as const;

export type PaletteKey = keyof typeof PALETTE;

export const BAND_KEYS: PaletteKey[] = ["teal", "mustard", "brick", "rose", "purple", "blue"];

/** The gradient treatment — teal to blue to rose, the sweep on the card back.
 *  A TREATMENT, not the mark. The flat mark is canonical. */
export const GRADIENT_STOPS = [
  { offset: "0%", color: PALETTE.teal.hex },
  { offset: "45%", color: PALETTE.blue.hex },
  { offset: "100%", color: PALETTE.rose.hex },
];

/**
 * TYPE — three voices, no more.
 *
 * Already true on the cards; named here so it holds off them too.
 *  PLATE   uppercase, heavily letterspaced sans. Names, labels, headings.
 *  CODE    mono. Classification codes, URLs, anything machine-issued.
 *  TRUE    ornate serif. The one line per surface that is the point.
 */
export const TYPE_VOICES = [
  {
    key: "plate",
    name: "Plate",
    use: "Names, designations, labels, headings, the seal's ring type.",
    css: "uppercase, tracking 0.16–0.2em, semibold",
  },
  {
    key: "code",
    name: "Code",
    use: "Classification codes, URLs, section labels. Anything issued by the Grid rather than written by a person.",
    css: "mono, uppercase, tracking 0.2–0.42em",
  },
  {
    key: "true",
    name: "True",
    use: "The one serif line per surface. Taglines, assignments. Never more than one voice-of-truth block.",
    css: "serif, often uppercase with tracking 0.09em",
  },
] as const;
